using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsPlatformOrnamentReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(f,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return pixels;}
 public static void Run(){const string ev="Evidence/Target34Platform";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget34Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);
 var pixels=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget34Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/prefab.png")),"Prefab reload pixels");
 var saved="Assets/RuinsTarget34Output/PlatformPersistence.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),saved);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene(saved);root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/scene.png")),"Scene reload pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget32Output/Structures/Ruins.prefab"));foreach(Transform t in root.transform){var b=old.transform.Find(t.name);if(b==null||!t.TryGetComponent<MeshFilter>(out var filter))continue;var prior=b.GetComponent<MeshFilter>().sharedMesh;Check(filter.sharedMesh.vertices.SequenceEqual(prior.vertices)&&filter.sharedMesh.normals.SequenceEqual(prior.normals)&&filter.sharedMesh.triangles.SequenceEqual(prior.triangles),"Geometry changed "+t.name);Check(t.GetComponent<MeshCollider>().sharedMesh==filter.sharedMesh,"Collider identity "+t.name);}
 foreach(var obj in new[]{root,old})foreach(int id in new[]{17,19})obj.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var before=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-before.png");old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-after.png")),"Other part appearance changed");
 foreach(var obj in new[]{root,old})foreach(Transform child in obj.transform)child.gameObject.SetActive(new[]{"ruins_17","ruins_18","ruins_19"}.Contains(child.name));var center=root.transform.Find("ruins_17").GetComponent<MeshRenderer>().bounds.center;
 foreach(var view in new[]{"normal","close","opposite"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographic=true;c.orthographicSize=view=="normal"?4.4f:2.9f;var pos=center+new Vector3(-7,5,8);root.SetActive(false);old.SetActive(true);Shot(c,pos,center,ev+"/before-"+view+".png");old.SetActive(false);root.SetActive(true);Shot(c,pos,center,ev+"/after-"+view+".png");}
 sun.transform.rotation=Quaternion.Euler(38,-28,0);foreach(Transform t in root.transform)t.gameObject.SetActive(t.name=="ruins_19");var edge=root.transform.Find("ruins_19").GetComponent<MeshRenderer>().bounds.center;c.orthographicSize=1.9f;Shot(c,edge+new Vector3(-4,3,5),edge,ev+"/edge-close.png");
 foreach(int id in new[]{17,19}){var template=root.transform.Find("ruins_"+id).gameObject;foreach(int n in new[]{9,225}){var clones=Enumerable.Range(0,n).Select(i=>{var o=UnityEngine.Object.Instantiate(template);o.transform.position=new Vector3(100+i*6,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"geometryAndCollidersUnchanged\":true,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"shared9And225\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
